#!/usr/bin/env node
import { main } from '../src/cli/cli.js';

process.exitCode = await main(process.argv.slice(2), {
  dir: process.env.ACCOUNTS_DIR ?? 'data',
  out: (line) => console.log(line),
});

import { createKv } from '../storage/kv.js';
import { createSessions } from '../services/sessions.js';
import { createSettings } from '../services/settings.js';
import { createUsers } from '../services/users.js';

// Runs one command and resolves to the exit code.
export async function main(argv, { dir, out, clock }) {
  const kv = createKv(dir);
  const users = createUsers(kv);
  const sessions = createSessions(kv, clock ? { clock } : {});
  const settings = createSettings(kv);
  const [command, ...a] = argv;
  try {
    switch (command) {
      case 'user-add':
        out('created ' + (await users.create(a[0])).id);
        return 0;
      case 'user-list':
        for (const user of await users.list()) out(user.id + ' ' + user.name);
        return 0;
      case 'user-rename':
        await users.rename(a[0], a[1]);
        out('renamed ' + a[0]);
        return 0;
      case 'session-start': {
        const user = await users.get(a[0]);
        if (!user) throw new Error('user not found: ' + a[0]);
        out(await sessions.start(user.id));
        return 0;
      }
      case 'set': {
        const value = /^\d+$/.test(a[2] ?? '') ? Number(a[2]) : a[2];
        await settings.set(a[0], a[1], value);
        out('ok');
        return 0;
      }
      case 'get':
        out(String(await settings.get(a[0], a[1])));
        return 0;
      default:
        out('usage: accounts <user-add|user-list|user-rename|session-start|set|get> ...');
        return 1;
    }
  } catch (err) {
    out('error: ' + err.message);
    return 1;
  }
}

import { systemClock } from '../util/clock.js';
import { newToken } from '../util/tokens.js';

export function createSessions(kv, { clock = systemClock, ttlMs = 3_600_000 } = {}) {
  return {
    // Resolves to the new token.
    async start(userId) {
      const token = newToken();
      await kv.set('session:' + token, { userId, expiresAt: clock.now() + ttlMs });
      return token;
    },
    // Resolves to the user id, or undefined for an unknown or expired token.
    // An expired session is deleted.
    async check(token) {
      const session = await kv.get('session:' + token);
      if (!session) return undefined;
      if (clock.now() >= session.expiresAt) {
        await kv.delete('session:' + token);
        return undefined;
      }
      return session.userId;
    },
    async end(token) {
      await kv.delete('session:' + token);
    },
  };
}

export const DEFAULTS = { theme: 'light', pageSize: 20 };

function validate(name, value) {
  if (!(name in DEFAULTS)) throw new Error('unknown setting: ' + name);
  if (name === 'theme' && !['light', 'dark'].includes(value))
    throw new RangeError('theme must be light or dark');
  if (name === 'pageSize' && !(Number.isInteger(value) && value >= 1 && value <= 100))
    throw new RangeError('pageSize must be an integer from 1 to 100');
}

export function createSettings(kv) {
  const read = async (userId) => (await kv.get('settings:' + userId)) ?? {};
  return {
    // Resolves to the stored value or the default.
    async get(userId, name) {
      if (!(name in DEFAULTS)) throw new Error('unknown setting: ' + name);
      return (await read(userId))[name] ?? DEFAULTS[name];
    },
    async set(userId, name, value) {
      validate(name, value);
      await kv.set('settings:' + userId, { ...(await read(userId)), [name]: value });
    },
    // Resolves to the defaults overlaid with stored values.
    async all(userId) {
      return { ...DEFAULTS, ...(await read(userId)) };
    },
  };
}

const idNumber = (id) => Number(id.slice(1));

export function createUsers(kv) {
  return {
    async create(name) {
      if (typeof name !== 'string' || !name.trim())
        throw new TypeError('name is required');
      const next = ((await kv.get('user-seq')) ?? 0) + 1;
      const user = { id: 'u' + next, name: name.trim() };
      await kv.set('user-seq', next);
      await kv.set('user:' + user.id, user);
      return user;
    },
    // Resolves to the user, or undefined when there is none.
    get(id) {
      return kv.get('user:' + id);
    },
    async rename(id, name) {
      const user = await kv.get('user:' + id);
      if (!user) throw new Error('user not found: ' + id);
      const renamed = { ...user, name: String(name).trim() };
      await kv.set('user:' + id, renamed);
      return renamed;
    },
    // Resolves to all users in id order.
    async list() {
      const ids = (await kv.keys())
        .filter((key) => key.startsWith('user:'))
        .map((key) => key.slice(5))
        .sort((a, b) => idNumber(a) - idNumber(b));
      const users = [];
      for (const id of ids) users.push(await kv.get('user:' + id));
      return users;
    },
  };
}

import { mkdir, readdir, readFile, rm, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

const fileFor = (dir, key) => join(dir, encodeURIComponent(key) + '.json');

// A key-value store with one JSON file per key. Every method returns a promise.
export function createKv(dir) {
  return {
    // Resolves to the value, or undefined for a missing key.
    async get(key) {
      let text;
      try {
        text = await readFile(fileFor(dir, key), 'utf8');
      } catch (err) {
        if (err.code === 'ENOENT') return undefined;
        throw err;
      }
      return JSON.parse(text);
    },
    async set(key, value) {
      await mkdir(dir, { recursive: true });
      await writeFile(fileFor(dir, key), JSON.stringify(value));
    },
    async delete(key) {
      await rm(fileFor(dir, key), { force: true });
    },
    // Resolves to every stored key, sorted.
    async keys() {
      let names;
      try {
        names = await readdir(dir);
      } catch (err) {
        if (err.code === 'ENOENT') return [];
        throw err;
      }
      return names
        .filter((name) => name.endsWith('.json'))
        .map((name) => decodeURIComponent(name.slice(0, -5)))
        .sort();
    },
  };
}
